1	// Recording an event page through ScraperAPI — the project's ONE page-fetching
2	// surface (the gcec RULES.md extractor-pipeline rule), beside its only caller.
3	// Swap the vendor here if ScraperAPI underperforms.
4	//
5	// Only usable from a task's `agent_preprocessing` worker: it needs
6	// SCRAPER_API_KEY, which the task names in `required_secrets` — the wiring
7	// converge stamps that into the scheduler workflow, so it reaches an Action-side
8	// worker and nothing else (an executor session holds no repo secrets). This
9	// sandbox is bot-blocked, so a direct fetch from a session would fail even with
10	// a key.
11	
12	import { mkdirSync, writeFileSync, statSync } from 'node:fs';
13	import { dirname } from 'node:path';
14	
15	// The ScraperAPI request URL for a page. `render=true` executes the page's JS so a
16	// single-page app records real content instead of an empty shell; the optional
17	// wait-for selector (the extension derives it from the live page, #603) makes the
18	// snapshot wait for real content to appear first. Both are url-encoded, so their
19	// own &/?/# can never leak as sibling ScraperAPI params.
20	export function scraperUrl(key, pageUrl, waitSelector) {
21	  const params = new URLSearchParams({ api_key: key, render: 'true', url: pageUrl });
22	  if (waitSelector) params.set('wait_for_selector', waitSelector);
23	  return `https://api.scraperapi.com/?${params}`;
24	}
25	
26	// Statuses worth another attempt. ScraperAPI answers **500** when its own proxy
27	// rotation gave up on a request — routinely transient, and re-requesting the same
28	// URL often succeeds. 429 is rate limiting; 502/503/504 are their gateway. A 4xx
29	// other than 429 is about the request itself and never improves on a retry.
30	//
31	// This list exists because the retired fetch-page.yml fetched with
32	// `curl --retry 5 --retry-max-time 300`, and curl's `--retry` covers exactly
33	// 408/429/500/502/503/504. Porting the fetch to `fetch()` silently dropped that,
34	// and the first real request through the new pipeline (#759) died on a single 500
35	// the old workflow would have ridden out.
36	const RETRYABLE = new Set([408, 429, 500, 502, 503, 504]);
37	
38	const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
39	
40	// Record `pageUrl` to `outPath`. Returns the byte count written, or throws with a
41	// message written to land verbatim on a GitHub issue — the caller's job is to
42	// decide whether an unfetchable page is a dead end (hand it to a human) or a
43	// failure, not to re-diagnose it.
44	//
45	// `attempts` bounds the retries; the backoff is short because the whole call sits
46	// inside a task's `agent_preprocessing_timeout` (a hard SIGKILL), so the worst case
47	// has to stay well inside it: 4 attempts × 120s + ~50s of waiting. `backoffMs` is
48	// injectable so the tests exercise the retry path without sleeping through it — a
49	// suite that really waits 50s to prove a retry is one nobody runs.
50	export async function recordPage(key, { url, waitSelector }, outPath, { timeoutMs = 120_000, attempts = 4, backoffMs = [5_000, 15_000, 30_000] } = {}) {
51	  const waits = Array.isArray(backoffMs) ? backoffMs : [backoffMs];
52	  let lastError = '';
53	  for (let attempt = 1; attempt <= attempts; attempt += 1) {
54	    let res = null;
55	    try {
56	      res = await fetch(scraperUrl(key, url, waitSelector), { signal: AbortSignal.timeout(timeoutMs) });
57	    } catch (e) {
58	      lastError = `the request failed (${e.message})`;   // timeout / socket — always worth a retry
59	    }
60	    if (res?.ok) {
61	      const html = await res.text();
62	      // An empty body is the page telling us nothing rendered; retrying a
63	      // successful-but-empty fetch just spends the budget on the same answer.
64	      if (!html.trim()) throw new Error(`ScraperAPI returned an empty document for ${url}`);
65	      mkdirSync(dirname(outPath), { recursive: true });
66	      writeFileSync(outPath, html);
67	      return statSync(outPath).size;
68	    }
69	    if (res && !RETRYABLE.has(res.status)) {
70	      throw new Error(`ScraperAPI returned HTTP ${res.status} for ${url}`);
71	    }
72	    if (res) lastError = `ScraperAPI returned HTTP ${res.status}`;
73	    if (attempt < attempts) await sleep(waits[Math.min(attempt - 1, waits.length - 1)]);
74	  }
75	  throw new Error(`${lastError} for ${url}, and did not recover in ${attempts} attempts`);
76	}
77

